&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Experience working with machined parts, sheet metal, PCBs, cable assemblies, or electromechanical systems.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Experience with inspection equipment such as calipers, micrometers, height gauges, and CMM reports.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Proficiency&amp;nbsp;in root cause analysis, failure analysis, and problem-solving methodologies.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Experience&amp;nbsp;using data&amp;nbsp;analysis&amp;nbsp;tools&amp;nbsp;to&amp;nbsp;identify&amp;nbsp;trends&amp;nbsp;and&amp;nbsp;establish&amp;nbsp;metrics.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Good&amp;nbsp;communication&amp;nbsp;and interpersonal skills, with the ability to influence&amp;nbsp;and&amp;nbsp;drive supplier improvements&amp;nbsp;in a fast-paced start-up environment.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
