&lt;li style=&quot;margin-top: 0px; margin-bottom: 0px; vertical-align: middle; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: &#39;Times New Roman&#39;; font-size: 12.0pt;&quot;&gt;Support comfort through repositioning, mobility assistance, and skin integrity care &lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;margin-top: 0px; margin-bottom: 0px; vertical-align: middle; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: &#39;Times New Roman&#39;; font-size: 12.0pt;&quot;&gt;Provide light housekeeping to maintain a clean, safe, and comfortable environment &lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;margin-top: 0px; margin-bottom: 0px; vertical-align: middle; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: &#39;Times New Roman&#39;; font-size: 12.0pt;&quot;&gt;Offer respite support to caregivers and families &lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p style=&quot;margin: 0in; font-family: &#39;Times New Roman&#39;; font-size: 12.0pt;&quot;&gt;&lt;span style=&quot;font-weight: bold; font-size: 12pt;&quot;&gt;Support Comfort, Dignity &amp;amp; Quality of Life&lt;/span&gt;&lt;/p&gt;
